const ACHIEVEMENTS={"primer_quiz": {"icon": "🧠", "label": "Primer quiz del árbol de decisión superado"}, "flash_master": {"icon": "🃏", "label": "Todo el vocabulario del árbol explorado"}, "clasif_pro": {"icon": "🗂️", "label": "Clasificador de nodos cuadrados y redondos experto"}, "id_master": {"icon": "🔍", "label": "Identificador de piezas del árbol maestro"}, "reto_hero": {"icon": "🏆", "label": "Héroe del reto de los 30 segundos"}, "sopa_champ": {"icon": "🔤", "label": "Campeón de la sopa del árbol de decisión"}, "eval_ace": {"icon": "🎓", "label": "Evaluación final aprobada con honores"}, "lect_master": {"icon": "📖", "label": "Las 30 preguntas de comprensión lectora respondidas"}, "full_xp": {"icon": "👑", "label": "Etapa 2 de la Ruta de la Apuesta Medida completada"}};
function unlockAchievement(id){if(!ACHIEVEMENTS[id])return;if(unlockedAch.includes(id))return;unlockedAch.push(id);sfx('ach');showToast(ACHIEVEMENTS[id].icon+' ¡Logro desbloqueado! '+ACHIEVEMENTS[id].label);launchConfetti();renderAchPanel();saveProgress();}
function renderAchPanel(){const list=document.getElementById('achList');list.innerHTML='';Object.entries(ACHIEVEMENTS).forEach(([id,a])=>{const div=document.createElement('div');div.className='ach-item'+(unlockedAch.includes(id)?'':' locked');div.innerHTML=`<span class="ach-icon">${a.icon}</span><span>${a.label}</span>`;list.appendChild(div);});}
function toggleAchPanel(){sfx('click');document.getElementById('achPanel').classList.toggle('open');}
function showToast(msg){let t=document.querySelector('.toast');if(!t){t=document.createElement('div');t.className='toast';document.body.appendChild(t);}t.textContent=msg;t.style.display='block';clearTimeout(t._tid);t._tid=setTimeout(()=>t.style.display='none',3200);}
function launchConfetti(){const colors=['#4d7c0f','#d9f99d','#92400e','#fde68a','#00b894'];for(let i=0;i<60;i++){const c=document.createElement('div');c.className='confetti-piece';c.style.cssText=`left:${Math.random()*100}vw;background:${colors[Math.floor(Math.random()*colors.length)]};animation-duration:${0.8+Math.random()*1.5}s;animation-delay:${Math.random()*0.4}s;width:${6+Math.random()*6}px;height:${6+Math.random()*6}px;border-radius:${Math.random()>0.5?'50%':'2px'};`;document.body.appendChild(c);c.addEventListener('animationend',()=>c.remove());}}

