// ===================== FLASHCARD DATA =====================
const fcData=[{"w": "El árbol de decisión", "a": "🌳 <strong>La oferta puesta en el papel:</strong> cada camino posible con su número al final. No es un adorno para la presentación: es la herramienta que obliga a ver completas las opciones antes de firmar. Howard Raiffa lo enseñó como pieza central en «Decision Analysis» (1968)."}, {"w": "El nodo de decisión", "a": "🔲 Se dibuja <strong>cuadrado</strong> y ahí decide la familia: firmar o no, esperar, pedir un piloto. De un cuadrado salen las ramas que uno puede elegir, y por eso en un cuadrado no se promedia: <strong>se escoge la mejor</strong>."}, {"w": "El nodo de azar", "a": "⚪ Se dibuja <strong>redondo</strong> y ahí decide el azar: que la venta vaya bien, que llueva, que la máquina salga buena. Cada rama lleva su probabilidad y las de un mismo nodo <strong>suman uno</strong>. En lo redondo no se elige: se promedia."}, {"w": "La hoja", "a": "🍃 El final de cada rama, con su número: <strong>lo que se gana o se pierde si el camino termina ahí</strong>, en lempiras. Un árbol con hojas sin número no se puede resolver: es un dibujo, no una herramienta."}, {"w": "Resolver hacia atrás", "a": "🔙 De las hojas al tronco: en cada nodo redondo se <strong>promedia</strong> con las probabilidades, y en cada cuadrado se <strong>elige</strong> la rama que más vale. Raiffa lo llamó «promediar y replegar». Al llegar al tronco, la decisión ya está tomada."}, {"w": "La regla de la página", "a": "📄 El árbol entero cabe en <strong>una sola página</strong>, o no sirve. Un árbol de tres páginas no es más serio: es una forma de no decidir, porque nadie lo resuelve ni lo discute. Si no cabe, se poda."}, {"w": "La poda", "a": "✂️ Quitar del árbol las ramas que <strong>no cambian la decisión</strong>: los caminos rarísimos que pagan casi lo mismo, los detalles que dan igual por todas las ramas. Podar no es esconder: es dejar a la vista lo que decide."}, {"w": "La probabilidad de cruce", "a": "⚖️ El punto donde la decisión <strong>cambia de lado</strong>: por debajo conviene una rama y por encima la otra. Se encuentra moviendo la probabilidad en el papel hasta que las dos opciones valen lo mismo. Es la herramienta fina de esta etapa."}, {"w": "El análisis de sensibilidad", "a": "🎚️ Mover cada número del árbol y mirar <strong>si la decisión se mueve con él</strong>. Si sale igual con 30 que con 70 por ciento, no vale la pena afinar esa estimación; si cruza en 55 y la familia estima 60, ahí está todo el trabajo."}, {"w": "El valor de la información", "a": "💡 <strong>Cuánto vale saber antes de firmar.</strong> Se mide comparando el árbol con el dato y sin él: la diferencia es lo máximo que conviene pagar por conseguirlo. Si el estudio cuesta más que eso, se decide sin estudio."}, {"w": "La información perfecta", "a": "🔮 El techo: lo que valdría un informante que <strong>nunca se equivoca</strong>. Ningún dato real vale más que eso, así que sirve de tope rápido: si el estudio cuesta más que el techo, no hay ni que discutirlo."}, {"w": "El piloto barato", "a": "🧪 Un mes de prueba, una llamada a quien ya pasó por ahí, una tirada chica: <strong>información comprada barata en vez de adivinada cara</strong>. Casi siempre existe, y casi nunca se pide porque firmar parece más rápido."}, {"w": "Howard Raiffa (1968)", "a": "📘 Profesor de Harvard y autor de <strong>«Decision Analysis: Introductory Lectures on Choices under Uncertainty»</strong> (1968), el libro que enseñó a dibujar decisiones con cuadrados, redondos y ramas, y a preguntarse cuánto vale la información antes de comprarla."}, {"w": "«Smart Choices» (1999)", "a": "📗 De <strong>John S. Hammond, Ralph L. Keeney y Howard Raiffa</strong>: la versión para la casa y la oficina. Su lección para esta etapa: muchas malas decisiones no fallan en la cuenta, fallan antes, en cómo se planteó el problema y qué alternativas se pusieron sobre la mesa."}, {"w": "La rama de esperar", "a": "⏳ Casi toda oferta tiene una tercera rama que nadie dibuja: <strong>no decidir hoy</strong>, pedir un piloto, negociar el plazo. Si el árbol solo tiene «sí» y «no», suele estar mal dibujado."}, {"w": "El árbol fechado", "a": "🗓️ El árbol de la oferta real se dibuja, se resuelve y se guarda <strong>con fecha, antes de conocer el resultado</strong>. Es lo que permite revisar dentro de un año qué se sabía y qué se estimó, en vez de discutir de memoria."}];
let fcIdx=0;
function upFC(){document.getElementById('fcInner').classList.remove('flipped');document.getElementById('fcW').textContent=fcData[fcIdx].w;document.getElementById('fcA').innerHTML=fcData[fcIdx].a;document.getElementById('fcCtr').textContent=(fcIdx+1)+' / '+fcData.length;}
