const qzData=[{"q":"En un árbol de decisión, ¿qué distingue a los nodos cuadrados de los redondos?","o":["a) Los cuadrados van al principio y los redondos al final","b) En los cuadrados decide la familia; en los redondos decide el azar","c) Los cuadrados son ganancias y los redondos pérdidas","d) Es solo una costumbre de dibujo, sin significado"],"c":1,"e":"El cuadrado marca una elección propia; el redondo marca un punto donde el resultado no depende de uno, y cada rama que sale de él lleva su probabilidad."},{"q":"¿Qué lleva el final de cada rama del árbol?","o":["a) Una hoja con un número: lo que se gana o se pierde si el camino termina ahí","b) El nombre del responsable","c) Una probabilidad","d) La fecha de la oferta"],"c":0,"e":"Sin números en las hojas no hay nada que promediar ni que comparar: el árbol se vuelve un dibujo que no decide."},{"q":"¿En qué consiste resolver el árbol hacia atrás?","o":["a) En empezar por el tronco y avanzar hasta las hojas","b) En leerlo en voz alta de principio a fin","c) En borrar las ramas malas primero","d) En ir de las hojas al tronco: promediar en lo redondo y elegir en lo cuadrado"],"c":3,"e":"Raiffa lo llamó «promediar y replegar»: es la única dirección en la que los números están listos cuando se necesitan."},{"q":"¿Por qué el árbol tiene que caber en una sola página?","o":["a) Por ahorrar papel","b) Porque las probabilidades no caben en más","c) Porque un árbol que nadie puede resolver ni discutir no decide: es una forma de aplazar","d) Porque lo exige el formato de la ficha"],"c":2,"e":"Un árbol de tres páginas parece más serio y decide menos. Lo que no cambia la decisión se poda."},{"q":"¿Qué es la probabilidad de cruce?","o":["a) La probabilidad de la rama más probable","b) El punto donde la decisión cambia de lado: por debajo conviene una rama y por encima la otra","c) La suma de las probabilidades del árbol","d) La probabilidad de que la oferta se repita"],"c":1,"e":"Se encuentra moviendo la probabilidad en el papel hasta que las dos opciones valen exactamente lo mismo."},{"q":"La decisión sale igual con 30 que con 70 por ciento. ¿Qué se hace con la estimación?","o":["a) No se afina: ningún dato sobre esa probabilidad puede cambiar la decisión","b) Se paga un estudio para conocerla mejor","c) Se rehace el árbol hasta que la decisión dependa de ella","d) Se toma el promedio, 50 por ciento"],"c":0,"e":"Afinar un número que no cruza es pagar por información que no mueve nada. Se decide ya, con la estimación gruesa."},{"q":"El cruce está en 55 y la familia estima 60. ¿Qué significa?","o":["a) Que se firma sin más, porque 60 es mayor que 55","b) Que la estimación está mal hecha","c) Que ahí está todo el trabajo: un error chico voltea la decisión y la información vale","d) Que el árbol tiene ramas de más"],"c":2,"e":"Con el cruce pegado a la estimación, conviene buscar el dato más barato que la mueva antes de firmar."},{"q":"¿Cómo se mide cuánto vale un dato antes de firmar?","o":["a) Por lo que cobra quien lo vende","b) Por el tamaño del informe","c) Por la urgencia de la decisión","d) Resolviendo el árbol con el dato y sin él: la diferencia es lo máximo que conviene pagar"],"c":3,"e":"Ese es el valor de la información. Si el estudio cuesta más que esa diferencia, se decide sin estudio."},{"q":"¿Quién escribió «Decision Analysis: Introductory Lectures on Choices under Uncertainty» (1968)?","o":["a) Ralph L. Keeney","b) Howard Raiffa","c) John S. Hammond","d) Robert Schlaifer"],"c":1,"e":"Howard Raiffa, profesor de Harvard. En 1999 firmó además, con Hammond y Keeney, la versión para la casa: «Smart Choices»."},{"q":"El estudio cuesta L 12,000 y saberlo todo (la información perfecta) vale L 7,000 en el árbol. ¿Qué se hace?","o":["a) Se compra, porque saber más siempre ayuda","b) Se negocia el precio a L 10,000","c) No se compra: ningún dato real vale más que el techo de la información perfecta","d) Se compra la mitad del estudio"],"c":2,"e":"La información perfecta es el tope: si ni un informante infalible valdría ese precio, un estudio con errores vale menos todavía."}];
let qzIdx=0,qzSel=-1,qzDone=false;
function buildQz(){qzIdx=0;qzSel=-1;qzDone=false;showQz();}
