const identifyTaskDB=[{"s": "Donde decide la familia se dibuja un cuadrado.", "type": "El nodo de decisión"}, {"s": "Donde decide el azar se dibuja un redondo.", "type": "El nodo de azar"}, {"s": "Cada camino termina en un número en lempiras.", "type": "La hoja"}, {"s": "Se promedia en lo redondo y se elige en lo cuadrado.", "type": "Resolver hacia atrás"}, {"s": "Si no cabe en una página, se poda.", "type": "La regla de la página"}, {"s": "La probabilidad donde la decisión cambia de lado.", "type": "La probabilidad de cruce"}, {"s": "Lo máximo que conviene pagar por saber antes de firmar.", "type": "El valor de la información"}, {"s": "Lo que valdría un informante que nunca falla.", "type": "La información perfecta"}, {"s": "Una llamada, un mes de datos, una tirada chica.", "type": "El piloto barato"}, {"s": "Quitar las ramas que no cambian la decisión.", "type": "La poda"}];
const classifyTaskDB=[{"w": "Escribir la pregunta en una línea", "gen": "Dibujo", "n": "Una sola decisión por árbol", "g": "Paso 1", "t": "Plantear"}, {"w": "Dibujar el cuadrado con las opciones", "gen": "Dibujo", "n": "Incluida la de esperar", "g": "Paso 2", "t": "Plantear"}, {"w": "Dibujar los redondos del azar", "gen": "Dibujo", "n": "Sus ramas suman uno", "g": "Paso 3", "t": "Plantear"}, {"w": "Poner números en las hojas", "gen": "Dibujo", "n": "En lempiras", "g": "Paso 4", "t": "Plantear"}, {"w": "Promediar en los nodos redondos", "gen": "Cuenta", "n": "Cada hoja por su probabilidad, sumado", "g": "Paso 5", "t": "Resolver"}, {"w": "Elegir en los nodos cuadrados", "gen": "Cuenta", "n": "Se tacha la rama perdedora", "g": "Paso 5", "t": "Resolver"}, {"w": "Buscar la probabilidad de cruce", "gen": "Criterio", "n": "Donde la decisión cambia de lado", "g": "Paso 6", "t": "Afinar"}, {"w": "Comparar el cruce con la estimación", "gen": "Criterio", "n": "¿Cerca o lejos?", "g": "Paso 6", "t": "Afinar"}, {"w": "Calcular cuánto vale saber antes", "gen": "Criterio", "n": "Con el dato y sin él", "g": "Paso 7", "t": "Afinar"}, {"w": "Podar hasta que quepa en la página", "gen": "Dibujo", "n": "Lo que no cambia la decisión, fuera", "g": "Paso 2", "t": "Plantear"}];
const completeTaskDB=[{"s": "Donde decide la familia, el nodo es ___.", "opts": ["cuadrado", "redondo", "doble"], "ans": "cuadrado"}, {"s": "Donde decide el azar, el nodo es ___.", "opts": ["redondo", "cuadrado", "negro"], "ans": "redondo"}, {"s": "El árbol se resuelve de las hojas al ___.", "opts": ["tronco", "borde", "final"], "ans": "tronco"}, {"s": "El árbol entero tiene que caber en una ___.", "opts": ["página", "carpeta", "semana"], "ans": "página"}, {"s": "En los nodos redondos se ___.", "opts": ["promedia", "elige", "borra"], "ans": "promedia"}, {"s": "En los nodos cuadrados se ___.", "opts": ["elige", "promedia", "apuesta"], "ans": "elige"}, {"s": "Donde la decisión cambia de lado está el ___.", "opts": ["cruce", "tronco", "techo"], "ans": "cruce"}, {"s": "El techo de todo dato es la información ___.", "opts": ["perfecta", "barata", "nueva"], "ans": "perfecta"}];
const explainQuestions=[{"q": "Explica qué es un árbol de decisión y qué significan sus dos clases de nodos.", "ans": "Es la oferta puesta en el papel: un dibujo donde cada camino posible de la decisión termina en un número. Los nodos cuadrados son los puntos donde decide la familia: aceptar, rechazar, esperar, pedir un piloto. Los nodos redondos son los puntos donde decide el azar: que la venta vaya bien o mal, que llueva o no; de ellos salen ramas con su probabilidad, y las de un mismo nodo suman uno. Al final de cada rama va una hoja con lo que se gana o se pierde, en lempiras. Howard Raiffa lo enseñó como pieza central del análisis de decisiones en «Decision Analysis» (1968)."}, {"q": "Explica cómo se resuelve un árbol hacia atrás y por qué no puede resolverse hacia adelante.", "ans": "Se empieza por los nodos que solo tienen hojas colgando. En cada nodo redondo se promedia: cada hoja por su probabilidad, y se suma; ese promedio se escribe sobre el nodo. En cada nodo cuadrado se comparan las ramas y se elige la que más vale, tachando las demás. Se repite hacia el tronco hasta que queda un solo número y un solo camino: esa es la decisión. Raiffa lo llamó «promediar y replegar». Hacia adelante no se puede, porque al llegar a un cuadrado habría que comparar ramas cuyos promedios todavía no existen: la única dirección en la que los números están listos cuando se necesitan es de las hojas al tronco."}, {"q": "¿Por qué el árbol tiene que caber en una sola página, y qué es la poda?", "ans": "Porque un árbol que no se puede resolver ni discutir no decide nada: un árbol de tres páginas es una forma de no decidir, aunque parezca más serio. La poda es quitar las ramas que no cambian la decisión: los caminos rarísimos que pagan casi lo mismo, los detalles que dan igual por todas las ramas. Podar no es esconder información: es dejar a la vista lo que decide. La prueba de una buena poda es que la decisión sale igual con la rama podada dentro que fuera."}, {"q": "Explica qué es la probabilidad de cruce y para qué sirve, con un ejemplo en lempiras.", "ans": "Es la probabilidad exacta donde la decisión cambia de lado: por debajo conviene una rama y por encima la otra. Se encuentra moviendo la probabilidad en el papel hasta que las dos opciones valen lo mismo, y sirve para saber dónde gastar el esfuerzo de estimar. Ejemplo: una editorial ofrece L 25,000 por la exclusiva; vender por cuenta propia deja L 60,000 si va bien y L 10,000 si va mal. Las dos opciones empatan cuando 60p + 10(1 menos p) = 25, es decir en p = 0,30. Si la familia estima 4 de cada 10, está a diez puntos del cruce: un error mediano voltea la decisión, y por eso ahí vale la pena afinar. Si el cruce hubiera dado 0,05, se firmaba sin afinar nada."}, {"q": "Explica cómo se mide el valor de la información y qué papel juega la información perfecta.", "ans": "Se resuelve el árbol dos veces: como está, y suponiendo que el dato se conociera antes de decidir. La diferencia entre los dos resultados es lo máximo que conviene pagar por ese dato: si el estudio cuesta más, se decide sin estudio. La información perfecta es el techo: lo que valdría un informante que nunca se equivoca. Ningún dato real vale más que eso, así que sirve de tope rápido: si lo que cobra el estudio supera el techo, no hay ni que discutirlo. Y hay una regla de plazo: la información que llega después de la firma vale cero para esta decisión."}, {"q": "¿Qué es un piloto barato? Da dos ejemplos posibles para M.E.T.A.S y di qué decisión movería cada uno.", "ans": "Es información comprada chica y a tiempo, en vez de adivinada cara: un experimento pequeño que responde la misma pregunta que el contrato grande. Ejemplos: antes de pagar L 8,000 por rediseñar las diez fichas más vendidas, rediseñar una sola por L 800 y medir un mes si vende más; ese dato cae justo sobre el cruce de la decisión grande. O antes de firmar un año de alquiler por L 72,000, alquilar un salón por horas dos fines de semana: si en la prueba no llegan alumnos, la estimación cae debajo del cruce y el contrato no se firma. En los dos casos el piloto cuesta una fracción de la decisión que evita o confirma."}];
let ansVisible=false;
function genTask(){sfx('click');const type=document.getElementById('tgType').value;const count=parseInt(document.getElementById('tgCount').value);ansVisible=false;const out=document.getElementById('tgOut');out.innerHTML='';if(type==='identify')genIdentifyTask(out,count);else if(type==='classify')genClassifyTask(out,count);else if(type==='complete')genCompleteTask(out,count);else if(type==='explain')genExplainTask(out,count);fin('s-tareas');}
function _instrBlock(out,title,lines){const ib=document.createElement('div');ib.className='tg-instruction-block';ib.innerHTML=`<h4>📋 ${title}</h4>`+lines.map(l=>`<p>${l}</p>`).join('');out.appendChild(ib);}
function genIdentifyTask(out,count){_instrBlock(out,'Instrucción',['Copia en tu cuaderno; subraya, colorea o encierra el concepto técnico ilustrado en cada oración. Escribe al lado de qué concepto se trata.','<strong>Ejemplo:</strong> Donde decide la familia se dibuja un cuadrado. → <span style="color:var(--jade);font-weight:700;">El nodo de decisión</span>']);_pick(identifyTaskDB,Math.min(count,identifyTaskDB.length)).forEach((item,i)=>{const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.s}</strong><div style="border-bottom:1.5px solid var(--border);min-width:220px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.type}</div></div>`;out.appendChild(div);});}
function genClassifyTask(out,count){_instrBlock(out,'Instrucción',['Copia la siguiente tabla en tu cuaderno. Para cada elemento, completa su tipo, características, ámbito y función.']);const items=_pick(classifyTaskDB,Math.min(count,classifyTaskDB.length));const wrap=document.createElement('div');wrap.style.overflowX='auto';const th=(t,extra='')=>`<th style="padding:0.3rem 0.4rem;border:1px solid var(--border);font-size:0.72rem;text-align:center;${extra}">${t}</th>`;let html=`<table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:520px;"><thead><tr style="background:var(--pri-gl);">${th('Elemento','text-align:left;')}${th('Tipo')}${th('Características')}${th('Ámbito')}${th('Función')}</tr></thead><tbody>`;items.forEach(it=>{html+=`<tr><td style="padding:0.4rem 0.5rem;border:1px solid var(--border);font-weight:600;">${it.w}</td>`+Array(4).fill(`<td style="padding:0.4rem;border:1px solid var(--border);min-width:50px;"></td>`).join('')+'</tr>';});html+='</tbody></table>';wrap.innerHTML=html;out.appendChild(wrap);const ans=document.createElement('div');ans.className='tg-answer';ans.style.marginTop='0.8rem';ans.innerHTML='<strong>✅ Respuestas:</strong><br>'+items.map(it=>`<strong>${it.w}:</strong> Tipo: ${it.gen} | Características: ${it.n} | Ámbito: ${it.g} | Función: ${it.t}`).join('<br>');out.appendChild(ans);}
function genCompleteTask(out,count){_instrBlock(out,'Instrucción',['Copia y resuelve en tu cuaderno. Cada oración tiene un espacio ___. Elige y escribe la opción correcta.']);const pool=_shuffle([...completeTaskDB]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';const sent=item.s.replace('___','<span class="tg-blank" style="min-width:90px;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>');div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${sent}</strong><div style="margin-top:0.4rem;font-size:0.82rem;color:var(--gray);">📝 Opciones: <strong>${item.opts.join(' | ')}</strong></div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function genExplainTask(out,count){_instrBlock(out,'Instrucción',['Copia las siguientes preguntas en tu cuaderno y responde cada una de forma clara y argumentada.']);const pool=_shuffle([...explainQuestions]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.q}</strong><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.3rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function toggleAns(){ansVisible=!ansVisible;document.querySelectorAll('.tg-answer').forEach(el=>el.style.display=ansVisible?'block':'none');sfx('click');}

// ===================== SOPA DE LETRAS =====================
const sopaSets=[{"size":10,"grid":[["A","R","B","O","L","I","N","Z","G","P"],["F","H","O","V","B","R","Z","P","G","I"],["E","M","R","L","C","N","O","D","O","L"],["R","F","C","C","V","L","G","R","G","O"],["A","J","L","R","H","O","J","A","E","T"],["M","E","A","N","U","E","T","E","F","O"],["A","D","Z","M","B","C","P","O","D","A"],["D","S","A","O","Z","J","E","R","N","H"],["L","O","R","C","D","A","T","O","E","M"],["I","E","P","A","G","I","N","A","Z","O"]],"words":[{"w":"ARBOL","cells":[[0,0],[0,1],[0,2],[0,3],[0,4]]},{"w":"PILOTO","cells":[[0,9],[1,9],[2,9],[3,9],[4,9],[5,9]]},{"w":"NODO","cells":[[2,5],[2,6],[2,7],[2,8]]},{"w":"RAMA","cells":[[3,0],[4,0],[5,0],[6,0]]},{"w":"CRUCE","cells":[[3,2],[4,3],[5,4],[6,5],[7,6]]},{"w":"HOJA","cells":[[4,4],[4,5],[4,6],[4,7]]},{"w":"AZAR","cells":[[5,2],[6,2],[7,2],[8,2]]},{"w":"PODA","cells":[[6,6],[6,7],[6,8],[6,9]]},{"w":"DATO","cells":[[8,4],[8,5],[8,6],[8,7]]},{"w":"PAGINA","cells":[[9,2],[9,3],[9,4],[9,5],[9,6],[9,7]]}]}];
let currentSopaSetIdx=0,sopaFoundWords=new Set();
let sopaFirstClickCell=null,sopaPointerStartCell=null,sopaPointerMoved=false,sopaSelectedCells=[];
function getSopaCellSize(){const container=document.getElementById('sopaGrid');if(!container||!container.parentElement)return 28;const avail=container.parentElement.clientWidth-16;const set=sopaSets[currentSopaSetIdx];return Math.max(20,Math.min(32,Math.floor(avail/set.size)));}
function buildSopa(){const set=sopaSets[currentSopaSetIdx];const grid=document.getElementById('sopaGrid');grid.innerHTML='';const sz=getSopaCellSize();grid.style.gridTemplateColumns=`repeat(${set.size},${sz}px)`;grid.style.gridTemplateRows=`repeat(${set.size},${sz}px)`;sopaFirstClickCell=null;sopaSelectedCells=[];for(let r=0;r<set.size;r++)for(let c=0;c<set.size;c++){const cell=document.createElement('div');cell.className='sopa-cell';cell.style.width=sz+'px';cell.style.height=sz+'px';cell.style.fontSize=Math.max(11,sz-10)+'px';cell.textContent=set.grid[r][c];cell.dataset.row=r;cell.dataset.col=c;const alreadyFound=set.words.find(w=>sopaFoundWords.has(w.w)&&w.cells.some(([wr,wc])=>wr===r&&wc===c));if(alreadyFound)cell.classList.add('sopa-found');grid.appendChild(cell);}setupSopaEvents();const wl=document.getElementById('sopaWords');wl.innerHTML='';set.words.forEach(wObj=>{const sp=document.createElement('span');sp.className='sopa-w'+(sopaFoundWords.has(wObj.w)?' found':'');sp.id='sw-'+wObj.w;sp.textContent=wObj.w;wl.appendChild(sp);});}
function setupSopaEvents(){const grid=document.getElementById('sopaGrid');grid.onpointerdown=e=>{const cell=e.target.closest('.sopa-cell');if(!cell)return;e.preventDefault();grid.setPointerCapture(e.pointerId);sopaPointerStartCell=cell;sopaPointerMoved=false;cell.classList.add('sopa-sel');sopaSelectedCells=[cell];};grid.onpointermove=e=>{if(!sopaPointerStartCell)return;e.preventDefault();const el=document.elementFromPoint(e.clientX,e.clientY);const cell=el?el.closest('.sopa-cell'):null;if(!cell)return;const sr=parseInt(sopaPointerStartCell.dataset.row),sc=parseInt(sopaPointerStartCell.dataset.col);const er=parseInt(cell.dataset.row),ec=parseInt(cell.dataset.col);if(sr!==er||sc!==ec)sopaPointerMoved=true;document.querySelectorAll('.sopa-cell.sopa-sel').forEach(c=>c.classList.remove('sopa-sel'));sopaSelectedCells=[];getSopaPath(sr,sc,er,ec).forEach(([r,c])=>{const pc=document.querySelector(`#sopaGrid [data-row="${r}"][data-col="${c}"]`);if(pc){pc.classList.add('sopa-sel');sopaSelectedCells.push(pc);}});};grid.onpointerup=e=>{if(!sopaPointerStartCell)return;e.preventDefault();grid.releasePointerCapture(e.pointerId);if(sopaPointerMoved&&sopaSelectedCells.length>1){checkSopaSelection();}else{const cell=sopaPointerStartCell;document.querySelectorAll('.sopa-cell.sopa-sel').forEach(c=>c.classList.remove('sopa-sel'));sopaSelectedCells=[];if(!sopaFirstClickCell){sopaFirstClickCell=cell;cell.classList.add('sopa-start');}else if(sopaFirstClickCell===cell){cell.classList.remove('sopa-start');sopaFirstClickCell=null;}else{const sr=parseInt(sopaFirstClickCell.dataset.row),sc=parseInt(sopaFirstClickCell.dataset.col);const er=parseInt(cell.dataset.row),ec=parseInt(cell.dataset.col);sopaFirstClickCell.classList.remove('sopa-start');sopaFirstClickCell=null;getSopaPath(sr,sc,er,ec).forEach(([r,c])=>{const pc=document.querySelector(`#sopaGrid [data-row="${r}"][data-col="${c}"]`);if(pc){pc.classList.add('sopa-sel');sopaSelectedCells.push(pc);}});checkSopaSelection();}}sopaPointerStartCell=null;sopaPointerMoved=false;};}
function getSopaPath(r1,c1,r2,c2){const dr=Math.sign(r2-r1),dc=Math.sign(c2-c1);const lr=Math.abs(r2-r1),lc=Math.abs(c2-c1);if(lr!==0&&lc!==0&&lr!==lc)return[[r1,c1]];const len=Math.max(lr,lc);const path=[];for(let i=0;i<=len;i++)path.push([r1+dr*i,c1+dc*i]);return path;}
function checkSopaSelection(){const set=sopaSets[currentSopaSetIdx];const word=sopaSelectedCells.map(c=>c.textContent).join('');const wordRev=word.split('').reverse().join('');const found=set.words.find(wObj=>!sopaFoundWords.has(wObj.w)&&(wObj.w===word||wObj.w===wordRev));if(found){sopaFoundWords.add(found.w);found.cells.forEach(([r,c])=>{const cell=document.querySelector(`#sopaGrid [data-row="${r}"][data-col="${c}"]`);if(cell){cell.classList.remove('sopa-sel','sopa-start');cell.classList.add('sopa-found');}});const sp=document.getElementById('sw-'+found.w);if(sp)sp.classList.add('found');if(!xpTracker.sopa.has(found.w)){xpTracker.sopa.add(found.w);pts(1);}sfx('ok');if(sopaFoundWords.size===set.words.length){fin('s-sopa');sfx('fan');showToast('🎉 ¡Todas las palabras encontradas!');}else showToast('✅ ¡Encontraste: '+found.w+'!');}else sfx('no');document.querySelectorAll('.sopa-cell.sopa-sel').forEach(c=>c.classList.remove('sopa-sel'));sopaSelectedCells=[];}
function nextSopaSet(){sfx('click');sopaFoundWords=new Set();currentSopaSetIdx=(currentSopaSetIdx+1)%sopaSets.length;buildSopa();showToast('🔄 Nueva sopa cargada');}
let _sopaResizeTimer=null;
window.addEventListener('resize',()=>{clearTimeout(_sopaResizeTimer);_sopaResizeTimer=setTimeout(()=>{if(document.getElementById('s-sopa').classList.contains('active'))buildSopa();},200);});

