const evalTFBank=[{"q": "En un árbol de decisión, los nodos cuadrados marcan los puntos donde decide la familia.", "a": true}, {"q": "Los nodos redondos marcan los puntos donde decide el azar, y sus ramas suman uno.", "a": true}, {"q": "El árbol se resuelve del tronco hacia las hojas.", "a": false}, {"q": "En un nodo redondo se elige la rama que más paga.", "a": false}, {"q": "En un nodo cuadrado se elige la rama que más vale, con los promedios ya calculados.", "a": true}, {"q": "Un árbol de tres páginas es más serio que uno de una página.", "a": false}, {"q": "La poda quita las ramas que no cambian la decisión.", "a": true}, {"q": "La probabilidad de cruce es el punto donde la decisión cambia de lado.", "a": true}, {"q": "Si la decisión es la misma con 30 que con 70 por ciento, vale la pena pagar por afinar la estimación.", "a": false}, {"q": "Si el cruce está en 55 y la familia estima 60, un error pequeño puede voltear la decisión.", "a": true}, {"q": "El valor de la información se mide comparando el árbol con el dato y sin él.", "a": true}, {"q": "Ningún dato real vale más que la información perfecta.", "a": true}, {"q": "La información que llega después de la firma vale igual que la que llega antes.", "a": false}, {"q": "«Decision Analysis» (1968) es obra de Howard Raiffa.", "a": true}, {"q": "«Smart Choices» (1999) lo escribieron Hammond, Keeney y Raiffa.", "a": true}];
const evalMCBank=[{"q":"¿Qué marca un nodo cuadrado en el árbol?","o":["a) Donde decide el azar","b) El final de un camino","c) Donde decide la familia","d) Una rama podada"],"a":2},{"q":"¿Qué marca un nodo redondo?","o":["a) Donde decide la familia","b) Donde decide el azar, con ramas que suman uno","c) El título del árbol","d) La rama de esperar"],"a":1},{"q":"¿Qué lleva cada hoja del árbol?","o":["a) El número de lo que se gana o se pierde si el camino termina ahí","b) Una probabilidad","c) El nombre de quien decide","d) La fecha de la oferta"],"a":0},{"q":"¿En qué dirección se resuelve el árbol?","o":["a) Del tronco a las hojas","b) De izquierda a derecha","c) En el orden en que se dibujó","d) De las hojas al tronco, promediando y eligiendo"],"a":3},{"q":"¿Qué se hace en un nodo redondo al resolver?","o":["a) Se elige la rama que más paga","b) Se promedia: cada hoja por su probabilidad, sumado","c) Se tacha el nodo","d) Se pregunta a la familia"],"a":1},{"q":"¿Qué se hace en un nodo cuadrado al resolver?","o":["a) Se promedia con las probabilidades","b) Se lanza una moneda","c) Se elige la rama que más vale y se tachan las demás","d) Se espera al azar"],"a":2},{"q":"¿Por qué el árbol debe caber en una página?","o":["a) Porque un árbol que no se puede resolver ni discutir no decide: es una forma de aplazar","b) Por ahorrar papel","c) Porque las impresoras no dan para más","d) Porque lo manda el formato de la ficha"],"a":0},{"q":"¿Qué es la poda?","o":["a) Borrar las ramas que pagan poco","b) Esconder las ramas incómodas","c) Acortar los nombres de los nodos","d) Quitar las ramas que no cambian la decisión"],"a":3},{"q":"¿Qué es la probabilidad de cruce?","o":["a) La probabilidad de la rama mejor","b) El punto donde la decisión cambia de lado","c) La suma de las probabilidades","d) La probabilidad de que el árbol quepa"],"a":1},{"q":"La decisión sale igual con 30 que con 70 por ciento. ¿Qué se concluye?","o":["a) Que hay que pagar el estudio","b) Que el árbol está mal dibujado","c) Que no vale la pena afinar esa estimación: se decide ya","d) Que faltan ramas"],"a":2},{"q":"El cruce está en 55 y la familia estima 60. ¿Qué se concluye?","o":["a) Que ahí está todo el trabajo: un error chico voltea la decisión y la información vale","b) Que se firma sin más, porque 60 es mayor que 55","c) Que la estimación es inútil","d) Que hay que rehacer el árbol"],"a":0},{"q":"¿Cómo se mide el valor de la información?","o":["a) Por el prestigio de quien la vende","b) Por el número de páginas del informe","c) Por lo que costó conseguirla","d) Comparando el árbol con el dato y sin él: la diferencia es lo máximo a pagar"],"a":3},{"q":"¿Qué es la información perfecta?","o":["a) Un estudio sin erratas","b) La que da un experto con título","c) El techo: lo que valdría un informante que nunca se equivoca","d) La información gratuita"],"a":2},{"q":"¿Cuál de estos es un piloto barato?","o":["a) Firmar dos años de exclusiva para ver qué pasa","b) Rediseñar una sola ficha y medir un mes, antes de pagar por las diez","c) Comprar la máquina para saber si sirve","d) Encargar un estudio que llega después de la firma"],"a":1},{"q":"¿Quiénes escribieron «Smart Choices» (1999)?","o":["a) Raiffa y Schlaifer","b) Keeney y Howard solos","c) Hammond y Raiffa solos","d) John S. Hammond, Ralph L. Keeney y Howard Raiffa"],"a":3}];
